const crypto = require('crypto');
const item = $input.first();
const deny = () => [{ json: { valid: false } }];
let secret;
try { secret = $env.SELLF_WEBHOOK_SECRET; } catch { /* n8n 2.x blocks environment access by default. */ }
if (typeof secret !== 'string' || !secret.trim()) {
  secret = $('Configuration (EDIT ME)').first().json.webhookSecret;
}
if (typeof secret !== 'string' || !secret.trim() || secret.trim() === 'your-webhook-secret') {
  console.warn('Webhook secret is missing or still a placeholder; configure environment or Configuration (EDIT ME).');
  return deny();
}
if (!item.binary?.data) return deny();
let raw;
try { raw = await this.helpers.getBinaryDataBuffer(0, 'data'); } catch { return deny(); }
const header = item.json.headers?.['x-sellf-signature'];
if (typeof header !== 'string') return deny();
const match = /^t=(\d+),v1=([a-fA-F0-9]{64})$/.exec(header);
if (!match || Math.abs(Math.floor(Date.now() / 1000) - Number(match[1])) > 300) return deny();
const supplied = Buffer.from(match[2], 'hex');
const expected = crypto.createHmac('sha256', secret).update(match[1] + '.').update(raw).digest();
if (supplied.length !== expected.length || !crypto.timingSafeEqual(supplied, expected)) return deny();
try { return [{ json: { valid: true, body: JSON.parse(raw.toString('utf8')) } }]; }
catch { return deny(); }

const data = $input.first().json.body.data;

return [{
  json: {
    email: data.customer.email,
    firstName: data.customer.firstName || '',
    productName: data.product.name,
    amount: data.order.amount / 100,
    netAmount: data.order.netTotal != null ? Number(data.order.netTotal) / 100 : null,
    currency: data.order.currency.toUpperCase(),
    sessionId: data.order.sessionId,
    paymentIntentId: data.order.paymentIntentId,
    needsInvoice: data.invoice?.needsInvoice || false,
    invoiceNip: data.invoice?.nip || null,
    invoiceCompany: data.invoice?.companyName || null,
    invoiceAddress: data.invoice?.address || null,
    invoiceCity: data.invoice?.city || null,
    invoicePostalCode: data.invoice?.postalCode || null,
    invoiceCountry: data.invoice?.country || 'PL'
  }
}];

const d = $input.first().json;
const config = $('Configuration (EDIT ME)').first().json;
const today = new Date().toISOString().split('T')[0];

if (!d.sessionId) throw new Error('Missing sessionId');
const invoiceNumber = `FV/${d.sessionId}`;

const buyerCity = d.invoicePostalCode
  ? `${d.invoicePostalCode} ${d.invoiceCity}`
  : d.invoiceCity || '-';

const seller = {
  nip: config.sellerNip,
  name: config.sellerName,
  address: {
    street: config.sellerStreet,
    city: config.sellerCity
  }
};

return [{
  json: { eventKey: `sellf:${d.sessionId}`, invoice: {
    invoiceNumber,
    issueDate: today,
    saleDate: today,
    issuePlace: seller.address.city.split(' ').slice(1).join(' ') || 'Warszawa',
    currency: d.currency || 'PLN',
    type: 'VAT',
    seller,
    buyer: {
      nip: d.invoiceNip,
      name: d.invoiceCompany || d.email,
      address: {
        street: d.invoiceAddress || '-',
        city: buyerCity,
        country: d.invoiceCountry || 'PL'
      }
    },
    items: [
      {
        name: d.productName,
        unit: 'szt.',
        quantity: 1,
        unitPrice: Math.round((d.netAmount ?? d.amount / (1 + Number(config.defaultVatRate) / 100)) * 100) / 100,
        vatRate: config.defaultVatRate
      }
    ],
    payment: {
      paid: true,
      date: today,
      method: 'transfer'
    },
    // Pass-through for error logging
    _meta: {
      sessionId: d.sessionId,
      paymentIntentId: d.paymentIntentId,
      buyerEmail: d.email
    }
  } }
}];

const input = $input.first().json;
const sd = $getWorkflowStaticData('global');
sd.invoices ??= [];
const key = input.eventKey;
if (!key) return [{ json: { success: false, error: 'missing order identifier' } }];
const previous = sd.invoices.find(entry => entry.key === key);
if (previous) return [{ json: { success: previous.status === 'sent', duplicate: true, status: previous.status, ksefNumber: previous.ksefNumber || null } }];
// Do not evict unresolved sends: capacity exhaustion requires operator reconciliation.
if (sd.invoices.length >= 1000) {
  const index = sd.invoices.findIndex(entry => entry.status === 'sent');
  if (index < 0) return [{ json: { success: false, error: 'deduplication capacity reached; reconcile unresolved invoices' } }];
  sd.invoices.splice(index, 1);
}
sd.invoices.push({ key, status: 'in_progress' });
return [{ json: { ...input, send: true } }];

const sd = $getWorkflowStaticData('global');
const entry = sd.invoices.find(e => e.key === $('Reserve Invoice').first().json.eventKey);
entry.status = 'not_accepted';
return [{ json: { success: false, status: entry.status, error: 'Gateway unavailable; reconcile before manual resend' } }];

const response = $input.first().json;
const reserved = $('Reserve Invoice').first().json;
const sd = $getWorkflowStaticData('global');
const entry = sd.invoices.find(e => e.key === reserved.eventKey);
const attempt = $runIndex;
const code = Number(response.statusCode);
const body = response.body;
const retryAfter = response.headers?.['retry-after'] ?? response.headers?.['Retry-After'];
let delay = /^\d+$/.test(String(retryAfter)) ? Number(retryAfter) : (Date.parse(retryAfter) - Date.now()) / 1000;
// A gateway JSON 503 may come AFTER starting an invoice: never retry it.
// Only a recognizable upstream HTML 503 (or an empty 503) is eligible.
const upstream503 = code === 503 && (body === '' || (typeof body === 'string' && /^\s*(<!doctype html|<html)/i.test(body)));
const throttled = code === 429 && Number.isFinite(delay) && delay >= 0 && delay <= 300;
const safe = upstream503 || throttled;
if (safe && attempt < 2) {
  delay = throttled ? Math.max(1, Math.ceil(delay)) : 5 * (2 ** attempt);
  return [{ json: { retry: true, delay } }];
}
const success = code >= 200 && code < 300 && body?.success === true && !!body?.data?.ksefNumber;
entry.status = success ? 'sent' : safe ? 'not_accepted' : 'uncertain';
if (success) entry.ksefNumber = body.data.ksefNumber;
return [{ json: { success, status: entry.status, ksefNumber: entry.ksefNumber || null,
  error: success ? null : 'Reconcile in KSeF before any manual resend' } }];
